		);
	}
}

if(!function_exists('is_safe_json')) {
	function is_safe_json(string $jsonString): bool
	{
		if (trim($jsonString) === '') {
			return false;
		}

		if (function_exists('json_validate')) {
			return json_validate($jsonString);
		}

		// Fallback for PHP < 8.3
		json_decode($jsonString);
		return json_last_error() === JSON_ERROR_NONE;
	}
}

/**
 * Sanitizes keywords used in generated package titles.
 *
 * @param string $kw Raw keyword value.
 *
 * @return string Sanitized keyword value.
 */

if (!function_exists('dy_sanitize_keywords')) {
	function dy_sanitize_keywords(string $kw): string
	{
		if($kw === '') {
			return '';
		}

		static $cache = [];
		$cache_key = 'dy_sanitize_keywords_' . $kw;

		if(array_key_exists($cache_key, $cache)) {
			return $cache[$cache_key];
		}

		$kw = trim(sanitize_text_field(wp_unslash($kw)));

		if ($kw === '') {
			return '';
		}

		$kw = strtolower(remove_accents($kw));

		$kw = preg_replace(
			[
				'/[^a-z0-9\s]/',
				'/\s+/',
			],
			['', ' '],
			$kw
		) ?? '';

		return $cache[$cache_key] = substr($kw, 0, 25);
	}
}



